+func pfParseWarning(result Result, path string) *ProviderWarning {
+	for i := range result.Warnings {
+		w := &result.Warnings[i]
+		if w.FilePath == path && (w.Code == "E_PARSE_ERROR" || w.Code == "E_PARSE_TIMEOUT") {
+			return w
+		}
+	}
+	return nil
+}
