func stripCodeLiteralsAndComments(content string) string {
	bytes := []byte(content)
	for i := 0; i < len(bytes); i++ {
		switch bytes[i] {
		case '"', '\'':
			quote := bytes[i]
			for j := i + 1; j < len(bytes); j++ {
				if bytes[j] == '\n' || bytes[j] == '\r' {
					i = j
					break
				}
				if bytes[j] == '\\' {
					j++
					continue
				}
				if bytes[j] == quote {
					maskBytes(bytes, i, j+1)
					i = j
					break
				}
			}
		case '`':
			for j := i + 1; j < len(bytes); j++ {
				if bytes[j] == '\\' {
					j++
					continue
				}
				if bytes[j] == '`' {
					maskBytes(bytes, i, j+1)
					i = j
					break
				}
			}
		case '/':
			if i+1 >= len(bytes) {
				continue
			}
			switch bytes[i+1] {
			case '/':
				j := i + 2
				for j < len(bytes) && bytes[j] != '\n' && bytes[j] != '\r' {
					j++
				}
				maskBytes(bytes, i, j)
				i = j
			case '*':
				j := i + 2
				for j+1 < len(bytes) && !(bytes[j] == '*' && bytes[j+1] == '/') {
					j++
				}
				if j+1 < len(bytes) {
					j += 2
				}
				maskBytes(bytes, i, j)
				i = j
			}
		}
	}
	return string(bytes)
}

func maskBytes(bytes []byte, start, end int) {
	if start < 0 {
		start = 0
	}
	if end > len(bytes) {
		end = len(bytes)
	}
	for i := start; i < end; i++ {
		if bytes[i] != '\n' && bytes[i] != '\r' {
			bytes[i] = ' '
		}
	}
}

