func TestTypeScriptSameFileNamespaceCallResolvesExactQualifiedTarget(t *testing.T) {
	repo := t.TempDir()
	writeFile(t, repo, "src/parser.ts", `export function run() {
  B.parse();
}

namespace A {
  export function parse() {}
}

namespace B {
  export function parse() {}
}
`)

	snapshot, err := BuildProviderSnapshot(t.Context(), repo, "test-version")
	if err != nil {
		t.Fatal(err)
	}
	byID := map[string]SymbolRecord{}
	for _, symbol := range snapshot.Symbols {
		byID[symbol.ID] = symbol
	}
	var targets []SymbolRecord
	for _, relation := range snapshot.Relations {
		if relation.Type != "CALLS" || lastSegment(relation.FromID) != "run" {
			continue
		}
		target := byID[relation.ToID]
		if target.Name == "parse" {
			if relation.Resolution != "exact" {
				t.Fatalf("namespace call resolution = %q, want exact: %#v", relation.Resolution, relation)
			}
			targets = append(targets, target)
		}
	}
	if len(targets) != 1 || targets[0].QualifiedName != "B.parse" {
		t.Fatalf("namespace call targets = %#v, want only B.parse; symbols: %#v; calls: %#v", targets, snapshot.Symbols, relationsOfType(snapshot.Relations, "CALLS"))
	}
}

