type jsNamespaceScope struct {
	Name      string
	StartLine int
	EndLine   int
	startByte int
	endByte   int
}

// jsNamespaceScopes returns the lexical ranges of same-file namespaces. The
// TypeScript parser intentionally inventories functions inside a namespace as
// ordinary, unqualified function symbols, so call resolution needs the source
// range to distinguish same-named declarations in `namespace A` and
// `namespace B`.
func jsNamespaceScopes(fileContent string) []jsNamespaceScope {
	stripped := stripCodeLiteralsAndComments(fileContent)
	var scopes []jsNamespaceScope
	for _, match := range jsNamespaceRe.FindAllStringSubmatchIndex(stripped, -1) {
		if len(match) < 4 {
			continue
		}
		open := match[1] - 1
		if open < 0 || open >= len(stripped) || stripped[open] != '{' {
			continue
		}
		close := findMatchingStaticDelimiter(stripped, open, '{', '}')
		if close < 0 {
			continue
		}
		parts := strings.FieldsFunc(stripped[match[2]:match[3]], func(r rune) bool { return r == '.' })
		for i := range parts {
			parts[i] = strings.TrimSpace(parts[i])
		}
		name := strings.Join(parts, ".")
		if name == "" {
			continue
		}

		// Nested `namespace B {}` declarations inherit their enclosing path;
		// dotted declarations (`namespace A.B {}`) already carry the full path.
		parent := ""
		parentSpan := len(stripped) + 1
		for _, scope := range scopes {
			if scope.startByte < open && close < scope.endByte && scope.endByte-scope.startByte < parentSpan {
				parent = scope.Name
				parentSpan = scope.endByte - scope.startByte
			}
		}
		if parent != "" && name != parent && !strings.HasPrefix(name, parent+".") {
			name = parent + "." + name
		}
		scopes = append(scopes, jsNamespaceScope{
			Name:      name,
			StartLine: 1 + strings.Count(stripped[:open], "\n"),
			EndLine:   1 + strings.Count(stripped[:close], "\n"),
			startByte: open,
			endByte:   close,
		})
	}
	return scopes
}

// jsNamespaceCallIdentifiers preserves the full qualified call name only when
// its receiver path names a namespace declared in the same file. Imported
// module receivers are resolved separately by importedReceiverCallRelations,
// while ordinary object receivers belong to receiverCallRelations. Keeping the
// qualifier prevents `B.parse()` from collapsing to the first local `parse`.
func jsNamespaceCallIdentifiers(content string, scopes []jsNamespaceScope) map[string]struct{} {
	namespaces := map[string]bool{}
	for _, scope := range scopes {
		namespaces[scope.Name] = true
	}

	out := map[string]struct{}{}
	stripped := stripCodeLiteralsAndComments(content)
	for _, match := range jsDottedCallRe.FindAllStringSubmatch(stripped, -1) {
		if len(match) < 2 {
			continue
		}
		parts := strings.FieldsFunc(match[1], func(r rune) bool { return r == '.' })
		for i := range parts {
			parts[i] = strings.TrimSpace(parts[i])
		}
		if len(parts) < 2 {
			continue
		}
		namespace := strings.Join(parts[:len(parts)-1], ".")
		if !namespaces[namespace] {
			continue
		}
		qualified := namespace + "." + parts[len(parts)-1]
		if parts[len(parts)-1] != "" {
			out[qualified] = struct{}{}
		}
	}
	return out
}

func jsNamespaceAtLine(scopes []jsNamespaceScope, line int) string {
	name := ""
	bestSpan := int(^uint(0) >> 1)
	for _, scope := range scopes {
		if line < scope.StartLine || line > scope.EndLine {
			continue
		}
		span := scope.EndLine - scope.StartLine
		if span < bestSpan {
			name = scope.Name
			bestSpan = span
		}
	}
	return name
}

