// jsNamespaceCallIdentifiers preserves the full qualified call name only when
// its receiver path names a namespace declared in the same file. A relative
// path inside a namespace (`B.parse()` inside `A`) is canonicalized to `A.B`.
// Imported module receivers are resolved separately, while ordinary object
// receivers belong to receiverCallRelations; a parameter/local binding that
// shadows the receiver root therefore suppresses namespace classification.
func jsNamespaceCallIdentifiers(content string, scopes []jsNamespaceScope, callerNamespace string, shadowed map[string]bool) map[string]struct{} {
	namespaces := map[string]bool{}
	for _, scope := range scopes {
		namespaces[scope.Name] = true
	}

	out := map[string]struct{}{}
	stripped := stripCodeLiteralsAndComments(content)
	for _, match := range jsDottedCallRe.FindAllStringSubmatch(stripped, -1) {
		if len(match) < 2 {
			continue
		}
		parts := strings.FieldsFunc(match[1], func(r rune) bool { return r == '.' })
		for i := range parts {
			parts[i] = strings.TrimSpace(parts[i])
		}
		if len(parts) < 2 {
			continue
		}
		if shadowed[parts[0]] {
			continue
		}
		namespace := jsCanonicalNamespace(strings.Join(parts[:len(parts)-1], "."), callerNamespace, namespaces)
		if namespace == "" {
			continue
		}
		qualified := namespace + "." + parts[len(parts)-1]
		if parts[len(parts)-1] != "" {
			out[qualified] = struct{}{}
		}
	}
	return out
}

func jsCanonicalNamespace(path, callerNamespace string, namespaces map[string]bool) string {
	for prefix := callerNamespace; prefix != ""; {
		candidate := prefix + "." + path
		if namespaces[candidate] {
			return candidate
		}
		if dot := strings.LastIndex(prefix, "."); dot >= 0 {
			prefix = prefix[:dot]
		} else {
			prefix = ""
		}
	}
	if namespaces[path] {
		return path
	}
	return ""
}

// jsParameterNames extracts TypeScript/JavaScript parameter bindings used to
// prevent a parameter receiver from being mistaken for a same-file namespace.
// It accepts optional, rest, and defaulted parameters as well as constructor
// parameter-property modifiers (`private readonly B?: Client`). Local bindings
// are intentionally not collected here: function-wide suppression is not
// scope-accurate and can hide a valid call before or after a nested shadow.
func jsParameterNames(signature string) map[string]bool {
	out := map[string]bool{}
	start := strings.Index(signature, "(")
	end := strings.LastIndex(signature, ")")
	if start < 0 || end <= start {
		return out
	}
	for _, parameter := range splitTopLevelStaticComma(signature[start+1 : end]) {
		parameter = strings.TrimSpace(parameter)
		for _, modifier := range []string{"public", "protected", "private", "readonly", "override"} {
			for strings.HasPrefix(parameter, modifier+" ") || strings.HasPrefix(parameter, modifier+"\t") {
				parameter = strings.TrimSpace(parameter[len(modifier):])
			}
		}
		parameter = strings.TrimSpace(strings.TrimPrefix(parameter, "..."))
		if parameter == "" || !isJSIdentifierStart(parameter[0]) {
			continue
		}
		nameEnd := 1
		for nameEnd < len(parameter) && isJSIdentifierPart(parameter[nameEnd]) {
			nameEnd++
		}
		name := parameter[:nameEnd]
		if name != "this" {
			out[name] = true
		}
	}
	return out
}

// jsNamespaceBySymbolID maps existing symbols to their lexical namespace
// without changing their public identity. Declaration byte offsets distinguish
// nested/reopened namespace members even when several declarations share one
// source line; line ranges remain a fallback for unusual declaration forms.
func jsNamespaceBySymbolID(content string, symbols []SymbolRecord, scopes []jsNamespaceScope) map[string]string {
	stripped := stripCodeLiteralsAndComments(content)
	lineStarts := []int{0}
	for i := 0; i < len(stripped); i++ {
		if stripped[i] == '\n' {
			lineStarts = append(lineStarts, i+1)
		}
	}
	cursors := map[int]int{}
	out := map[string]string{}
	for _, symbol := range symbols {
		if symbol.sourceEndByte > symbol.sourceStartByte && symbol.sourceEndByte <= len(stripped) {
			if namespace := jsNamespaceAtByte(scopes, symbol.sourceStartByte); namespace != "" {
				out[symbol.ID] = namespace
			}
			continue
		}
		line := symbol.StartLine
		if line <= 0 || line > len(lineStarts) {
			continue
		}
		start := lineStarts[line-1]
		end := len(stripped)
		if line < len(lineStarts) {
			end = lineStarts[line] - 1
		}
		cursor := cursors[line]
		if cursor < start || cursor >= end {
			cursor = start
		}
		position := jsSymbolDeclarationPosition(stripped, symbol, cursor, end)
		if position < 0 && cursor != start {
			position = jsSymbolDeclarationPosition(stripped, symbol, start, end)
		}
		if position >= 0 {
			cursors[line] = position + len(symbol.Name)
			if namespace := jsNamespaceAtByte(scopes, position); namespace != "" {
				out[symbol.ID] = namespace
			}
			continue
		}
		if namespace := jsNamespaceAtLine(scopes, line); namespace != "" {
			out[symbol.ID] = namespace
		}
	}
	return out
}

func jsSymbolDeclarationPosition(content string, symbol SymbolRecord, start, end int) int {
	if symbol.Name == "" || start < 0 || end <= start || end > len(content) {
		return -1
	}
	name := regexp.QuoteMeta(symbol.Name)
	patterns := []string{}
	switch {
	case symbol.Kind == "function":
		patterns = append(patterns,
			`\b(?:async\s+)?function\s*\*?\s*(`+name+`)\b`,
			`\b(?:const|let|var)\s+(`+name+`)\b`,
		)
	case typeLikeKind(symbol.Kind):
		patterns = append(patterns, `\b(?:abstract\s+)?(?:class|interface|enum|type)\s+(`+name+`)\b`)
	case symbol.Kind == "method":
		patterns = append(patterns, `\b(`+name+`)\s*(?:<[^>\n;{}()]*>)?\s*\(`)
	default:
		patterns = append(patterns, `\b(`+name+`)\b`)
	}
	segment := content[start:end]
	for _, pattern := range patterns {
		match := regexp.MustCompile(pattern).FindStringSubmatchIndex(segment)
		if len(match) >= 4 {
			return start + match[2]
		}
	}
	return -1
}

