func kotlinPrimaryConstructorFieldEntities(content string) []Entity {
	var entities []Entity
	seen := map[string]bool{}
	for _, loc := range kotlinClassDeclarationRe.FindAllStringSubmatchIndex(content, -1) {
		if len(loc) < 4 {
