}

type commaSpan struct {
	Text       string
	Start, End int
}

func splitTopLevelCommaSpans(value string) []commaSpan {
	var spans []commaSpan
	start := 0
	depth := 0
	inString := byte(0)
	escaped := false
	for i := 0; i < len(value); i++ {
		ch := value[i]
		if inString != 0 {
			if escaped {
				escaped = false
				continue
			}
			if ch == '\\' {
				escaped = true
				continue
			}
			if ch == inString {
				inString = 0
			}
			continue
		}
		switch ch {
		case '\'', '"', '`':
			inString = ch
		case '(', '[', '{', '<':
			depth++
		case ')', ']', '}', '>':
			if depth > 0 {
				depth--
			}
		case ',':
			if depth == 0 {
				spans = append(spans, commaSpan{Text: value[start:i], Start: start, End: i})
				start = i + 1
			}
		}
	}
	if start <= len(value) {
		spans = append(spans, commaSpan{Text: value[start:], Start: start, End: len(value)})
	}
	return spans
}

