// suppressing the entire caller. A binding applies only to later calls in the
// same brace scope, so an outer `B.parse()` survives a nested `{ const B = ...;
// B.parse(); }`. Parameter bindings are handled separately by jsParameterNames.
func jsLexicalBindingShadowsAt(content, name string, callPosition int) bool {
