	for _, match := range jsLexicalBindingRe.FindAllStringSubmatchIndex(content[:callPosition], -1) {
		if len(match) < 4 || content[match[2]:match[3]] != name {
			continue
		}
		declarationOpen, declarationClose := jsBraceScopeAt(content, match[2])
		if declarationOpen == callOpen && declarationClose == callClose {
			return true
		}
	}
	return false
