+func protocolBuffersSyntax(content string) (protobufSyntaxKind, int, int) {
+	index := 0
+	if strings.HasPrefix(content, "\uFEFF") {
+		index = len("\uFEFF")
+	}
+	index = skipProtocolBuffersTrivia(content, index)
+	identifierStart := index
