+func maskProtocolBuffersBOM(content []byte) {
+	if len(content) >= len("\uFEFF") && string(content[:len("\uFEFF")]) == "\uFEFF" {
+		for index := 0; index < len("\uFEFF"); index++ {
+			content[index] = ' '
+		}
+	}
