// jsLexicalBindingShadowsAt handles local namespace-name shadows without
// suppressing the entire caller. A binding's brace scope shadows that scope
// and every descendant, regardless of declaration order (let/const TDZ and
// function/class hoisting); a nested binding does not shadow an outer call.
// Parameter bindings are handled separately by jsParameterNames.
func jsLexicalBindingShadowsAt(content, name string, callPosition int) bool {
	callOpen, callClose := jsBraceScopeAt(content, callPosition)
	for _, match := range jsLexicalBindingRe.FindAllStringSubmatchIndex(content, -1) {
		if len(match) < 6 || content[match[4]:match[5]] != name {
			continue
		}
		declarationOpen, declarationClose := jsBraceScopeAt(content, match[4])
		if declarationOpen <= callOpen && callClose <= declarationClose {
			return true
		}
	}
	return false
}

func jsBraceScopeAt(content string, position int) (int, int) {
	if position > len(content) {
		position = len(content)
	}
	stack := []int{}
	for index := 0; index < position; index++ {
		switch content[index] {
		case '{':
			stack = append(stack, index)
		case '}':
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
		}
	}
	if len(stack) == 0 {
		return -1, len(content)
	}
	open := stack[len(stack)-1]
	close := findMatchingStaticDelimiter(content, open, '{', '}')
	if close < 0 {
		close = len(content)
	}
	return open, close
}

func jsCanonicalNamespace(path, callerNamespace string, namespaces map[string]bool) string {
	for prefix := callerNamespace; prefix != ""; {
		candidate := prefix + "." + path
		if namespaces[candidate] {
			return candidate
		}
		if dot := strings.LastIndex(prefix, "."); dot >= 0 {
			prefix = prefix[:dot]
		} else {
			prefix = ""
		}
	}
	if namespaces[path] {
		return path
	}
	return ""
}

// jsParameterNames extracts TypeScript/JavaScript parameter bindings used to
// prevent a parameter receiver from being mistaken for a same-file namespace.
// It accepts optional, rest, and defaulted parameters as well as constructor
// parameter-property modifiers (`private readonly B?: Client`). Local bindings
// are intentionally not collected here: function-wide suppression is not
// scope-accurate and can hide a valid call before or after a nested shadow.
func jsParameterNames(signature string) map[string]bool {
	out := map[string]bool{}
	start := strings.Index(signature, "(")
	end := -1
	if start >= 0 {
		end = findMatchingStaticDelimiter(signature, start, '(', ')')
	}
	if start < 0 || end <= start {
		return out
	}
	for _, parameter := range jsSplitParameterList(signature[start+1 : end]) {
		parameter = strings.TrimSpace(parameter)
		for {
			removed := false
			for _, modifier := range []string{"public", "protected", "private", "readonly", "override"} {
				if strings.HasPrefix(parameter, modifier+" ") || strings.HasPrefix(parameter, modifier+"\t") {
					parameter = strings.TrimSpace(parameter[len(modifier):])
					removed = true
					break
				}
			}
			if !removed {
				break
			}
		}
		parameter = strings.TrimSpace(strings.TrimPrefix(parameter, "..."))
		if parameter == "" || !isJSIdentifierStart(parameter[0]) {
			continue
		}
		nameEnd := 1
		for nameEnd < len(parameter) && isJSIdentifierPart(parameter[nameEnd]) {
			nameEnd++
		}
		name := parameter[:nameEnd]
		if name != "this" {
			out[name] = true
		}
	}
	return out
}

func jsSplitParameterList(parameters string) []string {
	var parts []string
	start := 0
	parenDepth, bracketDepth, braceDepth, angleDepth := 0, 0, 0, 0
	for index := 0; index < len(parameters); index++ {
		switch parameters[index] {
		case '(':
			parenDepth++
		case ')':
			if parenDepth > 0 {
				parenDepth--
			}
		case '[':
			bracketDepth++
		case ']':
			if bracketDepth > 0 {
				bracketDepth--
			}
		case '{':
			braceDepth++
		case '}':
			if braceDepth > 0 {
				braceDepth--
			}
		case '<':
			angleDepth++
		case '>':
			if angleDepth > 0 {
				angleDepth--
			}
		case ',':
			if parenDepth == 0 && bracketDepth == 0 && braceDepth == 0 && angleDepth == 0 {
				parts = append(parts, parameters[start:index])
				start = index + 1
			}
		}
	}

