func clojureCallIdentifiers(content string) map[string]struct{} {
	stripped := stripCodeLiteralsAndComments(content)
	out := map[string]struct{}{}
	for _, match := range clojureCallHeadRe.FindAllStringSubmatch(stripped, -1) {
		if len(match) < 2 {
			continue
		}
		name := clojureCallableName(match[1])
		if name == "" || clojureCallNameIgnored(name) {
			continue
		}
		out[name] = struct{}{}
	}
	return out
}

func clojureCallableName(name string) string {
	name = strings.TrimSpace(name)
	if name == "" {
		return ""
	}
	if strings.Contains(name, "/") {
		parts := strings.Split(name, "/")
		name = parts[len(parts)-1]
	}
	return strings.Trim(name, ".")
}

func clojureCallNameIgnored(name string) bool {
	switch name {
	case ".", "..", "->", "->>", "as->", "case", "catch", "comment", "cond", "cond->", "cond->>", "def", "defmacro", "defmethod", "defmulti", "defn", "defn-", "defonce", "defprotocol", "defrecord", "deftype", "do", "doseq", "dotimes", "doto", "extend-protocol", "extend-type", "finally", "fn", "for", "if", "if-let", "if-not", "import", "let", "letfn", "loop", "new", "ns", "quote", "recur", "require", "set!", "throw", "try", "use", "var", "when", "when-let", "when-not", "while", "with-open":
		return true
	default:
		return strings.HasPrefix(name, ":")
	}
}

func sqlCallIdentifiers(content string) map[string]struct{} {
	stripped := stripSQLComments(content)
	out := map[string]struct{}{}
	for _, match := range sqlRoutineCallRe.FindAllStringSubmatch(stripped, -1) {
		if len(match) < 2 {
			continue
		}
		name := normalizeSQLDottedName(match[1])
		if strings.Contains(name, ".") {
			parts := strings.Split(name, ".")
			name = parts[len(parts)-1]
		}
		name = strings.TrimSpace(name)
		if name == "" || sqlCallNameIgnored(name) {
			continue
		}
		out[name] = struct{}{}
	}
	return out
}

func sqlCallNameIgnored(name string) bool {
	switch strings.ToLower(name) {
	case "array", "cast", "coalesce", "count", "date_part", "exists", "extract", "function", "greatest", "if", "least", "lower", "max", "min", "nullif", "procedure", "sum", "upper", "values":
		return true
	default:
		return false
	}
}

func jsDottedCallIdentifiers(content string) map[string]struct{} {
	return dottedCallIdentifiers(stripCodeLiteralsAndComments(content), jsDottedCallRe)
}

type jsNamespaceScope struct {
	Name      string
	StartLine int
	EndLine   int
	startByte int
	endByte   int
}

// jsNamespaceScopes returns the lexical ranges of same-file namespaces. The
// TypeScript parser intentionally inventories functions inside a namespace as
// ordinary, unqualified function symbols, so call resolution needs the source
// range to distinguish same-named declarations in `namespace A` and
// `namespace B`.
func jsNamespaceScopes(fileContent string) []jsNamespaceScope {
	stripped := stripCodeLiteralsAndComments(fileContent)
	var scopes []jsNamespaceScope
	for _, match := range jsNamespaceRe.FindAllStringSubmatchIndex(stripped, -1) {
		if len(match) < 4 {
			continue
		}
		open := match[1] - 1
		if open < 0 || open >= len(stripped) || stripped[open] != '{' {
			continue
		}
		close := findMatchingStaticDelimiter(stripped, open, '{', '}')
		if close < 0 {
			continue
		}
		parts := strings.FieldsFunc(stripped[match[2]:match[3]], func(r rune) bool { return r == '.' })
		for i := range parts {
			parts[i] = strings.TrimSpace(parts[i])
		}
		name := strings.Join(parts, ".")
		if name == "" {
			continue
		}

		// Nested `namespace B {}` declarations inherit their enclosing path;
		// dotted declarations (`namespace A.B {}`) already carry the full path.
		parent := ""
		parentSpan := len(stripped) + 1
		for _, scope := range scopes {
			if scope.startByte < open && close < scope.endByte && scope.endByte-scope.startByte < parentSpan {
				parent = scope.Name
				parentSpan = scope.endByte - scope.startByte
			}
		}
		if parent != "" && name != parent && !strings.HasPrefix(name, parent+".") {
			name = parent + "." + name
		}
		scopes = append(scopes, jsNamespaceScope{
			Name:      name,
			StartLine: 1 + strings.Count(stripped[:open], "\n"),
			EndLine:   1 + strings.Count(stripped[:close], "\n"),
			startByte: open,
			endByte:   close,
		})
	}
	return scopes
}

// jsNamespaceCallIdentifiers preserves the full qualified call name only when
// its receiver path names a namespace declared in the same file. A relative
// path inside a namespace (`B.parse()` inside `A`) is canonicalized to `A.B`.
// Imported module receivers are resolved separately, while ordinary object
// receivers belong to receiverCallRelations; a parameter/local binding that
// shadows the receiver root therefore suppresses namespace classification.
func jsNamespaceCallIdentifiers(content string, scopes []jsNamespaceScope, callerNamespace string, shadowed map[string]bool) map[string]struct{} {
	return jsNamespaceCallIdentifiersAt(content, scopes, callerNamespace, shadowed, jsFileBindingScopes(content, nil), 0)
}

func jsNamespaceCallIdentifiersAt(content string, scopes []jsNamespaceScope, callerNamespace string, shadowed map[string]bool, bindings []jsBindingScope, contentStartByte int) map[string]struct{} {
	namespaces := map[string]bool{}
	for _, scope := range scopes {
		namespaces[scope.Name] = true
	}

	out := map[string]struct{}{}
	stripped := stripCodeLiteralsAndComments(content)
	for _, match := range jsDottedCallRe.FindAllStringSubmatchIndex(stripped, -1) {
		if len(match) < 4 {
			continue
		}
		parts := strings.FieldsFunc(stripped[match[2]:match[3]], func(r rune) bool { return r == '.' })
		for i := range parts {
			parts[i] = strings.TrimSpace(parts[i])
		}
		if len(parts) < 2 {
			continue
		}
		if shadowed[parts[0]] || jsBindingShadowsAt(bindings, parts[0], contentStartByte+match[2]) {
			continue
		}
		namespace := jsCanonicalNamespace(strings.Join(parts[:len(parts)-1], "."), callerNamespace, namespaces)
		if namespace == "" {
			continue
		}
		qualified := namespace + "." + parts[len(parts)-1]
		if parts[len(parts)-1] != "" {
			out[qualified] = struct{}{}
		}
	}
	return out
}

type jsBindingScope struct {
	Name      string
	startByte int
	endByte   int
}

// jsFileBindingScopes produces one file-position binding view shared by every
// symbol scan. Parameter scopes naturally inherit into nested callables;
// lexical declarations inherit into descendant braces; and var declarations
// use the smallest containing callable range (function scope).
func jsFileBindingScopes(content string, symbols []SymbolRecord) []jsBindingScope {
	stripped := stripCodeLiteralsAndComments(content)
	var bindings []jsBindingScope
	for _, symbol := range symbols {
		if (symbol.Kind != "function" && symbol.Kind != "method") || symbol.sourceEndByte <= symbol.sourceStartByte {
			continue
		}
		for name := range jsParameterNames(symbol.Signature) {
			bindings = append(bindings, jsBindingScope{Name: name, startByte: symbol.sourceStartByte, endByte: symbol.sourceEndByte})
