	}
	add := func(kind, name string, position int) {
		if name == "" {
			return
		}
		start, end := jsBraceScopeAt(stripped, position)
		if kind == "var" {
			bestSpan := len(stripped) + 1
			for _, symbol := range symbols {
				if (symbol.Kind != "function" && symbol.Kind != "method") || symbol.sourceEndByte <= symbol.sourceStartByte || position < symbol.sourceStartByte || position >= symbol.sourceEndByte {
					continue
				}
				if span := symbol.sourceEndByte - symbol.sourceStartByte; span < bestSpan {
					start, end = symbol.sourceStartByte, symbol.sourceEndByte
					bestSpan = span
				}
			}
		}
		bindings = append(bindings, jsBindingScope{Name: name, startByte: start, endByte: end})
	}
	for _, match := range jsLexicalBindingRe.FindAllStringSubmatchIndex(stripped, -1) {
		if len(match) >= 6 {
			add(stripped[match[2]:match[3]], stripped[match[4]:match[5]], match[4])
		}
	}
	for _, match := range jsDestructuredBindingRe.FindAllStringSubmatchIndex(stripped, -1) {
		if len(match) < 6 {
			continue
		}
		kind := stripped[match[2]:match[3]]
		for _, property := range strings.Split(stripped[match[4]:match[5]], ",") {
			parts := jsBindingIdentifierRe.FindAllString(property, -1)
			if len(parts) > 0 {
				add(kind, parts[len(parts)-1], match[4])
			}
		}
	}
	return bindings
}

func jsBindingShadowsAt(bindings []jsBindingScope, name string, position int) bool {
	for _, binding := range bindings {
		if binding.Name == name && binding.startByte < position && position < binding.endByte {
			return true
		}
	}
	return false
}

// jsLexicalBindingShadowsAt handles local namespace-name shadows without
// suppressing the entire caller. A binding's brace scope shadows that scope
// and every descendant, regardless of declaration order (let/const TDZ and
// function/class hoisting); a nested binding does not shadow an outer call.
// Parameter bindings are handled separately by jsParameterNames.
func jsLexicalBindingShadowsAt(content, name string, callPosition int) bool {
	return jsBindingShadowsAt(jsFileBindingScopes(content, nil), name, callPosition)
}

func jsBraceScopeAt(content string, position int) (int, int) {
	if position > len(content) {
		position = len(content)
	}
	stack := []int{}
	for index := 0; index < position; index++ {
		switch content[index] {
		case '{':
			stack = append(stack, index)
		case '}':
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
		}
	}
	if len(stack) == 0 {
		return -1, len(content)
	}
	open := stack[len(stack)-1]
	close := findMatchingStaticDelimiter(content, open, '{', '}')
	if close < 0 {
		close = len(content)
	}
	return open, close
}

func jsCanonicalNamespace(path, callerNamespace string, namespaces map[string]bool) string {
	for prefix := callerNamespace; prefix != ""; {
		candidate := prefix + "." + path
		if namespaces[candidate] {
			return candidate
		}
		if dot := strings.LastIndex(prefix, "."); dot >= 0 {
			prefix = prefix[:dot]
		} else {
			prefix = ""
		}
	}
	if namespaces[path] {
		return path
	}
	return ""
}

