// jsFileBindingScopes produces one file-position binding view shared by every
// symbol scan. Parameter scopes naturally inherit into nested callables;
// lexical declarations inherit into descendant braces; and var declarations
// use the smallest containing callable range (function scope).
func jsFileBindingScopes(content string, symbols []SymbolRecord) []jsBindingScope {
	stripped := stripCodeLiteralsAndComments(content)
	namespaces := jsNamespaceScopes(content)
	var bindings []jsBindingScope
	for _, symbol := range symbols {
		if (symbol.Kind != "function" && symbol.Kind != "method") || symbol.sourceEndByte <= symbol.sourceStartByte {
			continue
		}
		for _, name := range jsSymbolParameterNames(symbol) {
			bindings = append(bindings, jsBindingScope{Name: name, startByte: symbol.sourceStartByte, endByte: symbol.sourceEndByte})
		}
	}
	add := func(kind, name string, position int) {
		if name == "" {
			return
		}
		start, end := jsBraceScopeAt(stripped, position)
		if (kind == "function" || kind == "class" || kind == "enum") && jsNamespaceMergesBinding(stripped, namespaces, name, start, end) {
			return
		}
		if kind == "var" {
			bestSpan := len(stripped) + 1
			for _, symbol := range symbols {
				if (symbol.Kind != "function" && symbol.Kind != "method") || symbol.sourceEndByte <= symbol.sourceStartByte || position < symbol.sourceStartByte || position >= symbol.sourceEndByte {
					continue
				}
				if span := symbol.sourceEndByte - symbol.sourceStartByte; span < bestSpan {
					start, end = symbol.sourceStartByte, symbol.sourceEndByte
					bestSpan = span
				}
			}
		}
		bindings = append(bindings, jsBindingScope{Name: name, startByte: start, endByte: end})
	}
	for _, match := range jsLexicalBindingRe.FindAllStringSubmatchIndex(stripped, -1) {
		if len(match) >= 6 {
			add(stripped[match[2]:match[3]], stripped[match[4]:match[5]], match[4])
		}
	}
	for _, match := range jsDestructuredBindingRe.FindAllStringSubmatchIndex(stripped, -1) {
		if len(match) < 6 {
			continue
		}
		kind := stripped[match[2]:match[3]]
		for _, name := range jsDestructuredNames(stripped[match[4]:match[5]], true) {
			add(kind, name, match[0])
		}
	}
	for _, match := range jsArrayBindingRe.FindAllStringSubmatchIndex(stripped, -1) {
		if len(match) < 6 {
			continue
		}
		kind := stripped[match[2]:match[3]]
		for _, name := range jsDestructuredNames(stripped[match[4]:match[5]], false) {
