// jsParameterNames extracts TypeScript/JavaScript parameter bindings used to
// prevent a parameter receiver from being mistaken for a same-file namespace.
// It accepts optional, rest, and defaulted parameters as well as constructor
// parameter-property modifiers (`private readonly B?: Client`). Local bindings
// are intentionally not collected here: function-wide suppression is not
// scope-accurate and can hide a valid call before or after a nested shadow.
func jsParameterNames(signature string) map[string]bool {
	out := map[string]bool{}
	start := strings.Index(signature, "(")
	end := -1
	if start >= 0 {
		end = findMatchingStaticDelimiter(signature, start, '(', ')')
	}
	if start < 0 || end <= start {
		return out
	}
	for _, parameter := range jsSplitParameterList(signature[start+1 : end]) {
		parameter = strings.TrimSpace(parameter)
		if strings.HasPrefix(parameter, "{") {
			if close := findMatchingStaticDelimiter(parameter, 0, '{', '}'); close > 0 {
				for _, name := range jsDestructuredNames(parameter[1:close], true) {
					out[name] = true
				}
			}
			continue
		}
		if strings.HasPrefix(parameter, "[") {
			if close := findMatchingStaticDelimiter(parameter, 0, '[', ']'); close > 0 {
				for _, name := range jsDestructuredNames(parameter[1:close], false) {
					out[name] = true
				}
			}
			continue
		}
		for {
			removed := false
			for _, modifier := range []string{"public", "protected", "private", "readonly", "override"} {
				if strings.HasPrefix(parameter, modifier+" ") || strings.HasPrefix(parameter, modifier+"\t") {
					parameter = strings.TrimSpace(parameter[len(modifier):])
					removed = true
					break
				}
			}
			if !removed {
				break
			}
		}
		parameter = strings.TrimSpace(strings.TrimPrefix(parameter, "..."))
		if parameter == "" || !isJSIdentifierStart(parameter[0]) {
			continue
		}
