	if enclosing := jsNamespaceAtByte(namespaces, position); enclosing != "" {
		canonicalName = enclosing + "." + name
	}
	for _, namespace := range namespaces {
		if namespace.Name != canonicalName {
			continue
		}
		parentStart, parentEnd := jsBraceScopeAt(content, namespace.startByte)
		if parentStart == bindingStart && parentEnd == bindingEnd {
			return true
		}
	}
	return false
}

func jsBindingShadowsAt(bindings []jsBindingScope, name string, position int) bool {
	for _, binding := range bindings {
		if binding.Name == name && binding.startByte < position && position < binding.endByte {
			return true
		}
	}
	return false
}

func jsSymbolParameterNames(symbol SymbolRecord) []string {
	if len(symbol.parameterNames) > 0 {
		return symbol.parameterNames
	}
	names := jsParameterNames(symbol.Signature)
	out := make([]string, 0, len(names))
	for name := range names {
		out = append(out, name)
	}
	return out
}

