// suppressing the entire caller. A binding's brace scope shadows that scope
// and every descendant, regardless of declaration order (let/const TDZ and
// function/class hoisting); a nested binding does not shadow an outer call.
// Parameter bindings are handled separately by jsParameterNames.
func jsLexicalBindingShadowsAt(content, name string, callPosition int) bool {
	return jsBindingShadowsAt(jsFileBindingScopes(content, nil), name, callPosition)
}

